# SPDX-License-Identifier: MIT
# What the monitor reads: Linux's own files (/proc and /sys: the cores' load, memory, temperature,
# network, uptime) and the Cortex-M4 (remoteproc's state, the firmware, the channel, a request's
# time there and back). In the LVGL MPY Studio simulator, made-up values.

import time

try:
    import mpy_m4

    HARDWARE = mpy_m4.available()
except ImportError:
    HARDWARE = False


def _read(path):
    with open(path) as f:
        return f.read()


class Board:
    def __init__(self):
        self._cpu = None
        self._net = None
        self._net_at = None

    def cpu(self):
        # Busy share of each core since the last call, from /proc/stat.
        now = []
        for line in _read("/proc/stat").split("\n"):
            if line.startswith("cpu") and line[3:4].isdigit():
                values = [int(v) for v in line.split()[1:]]
                idle = values[3] + values[4]
                now.append((sum(values), idle))
        before, self._cpu = self._cpu, now
        if not before:
            return [0] * len(now)
        return [100 * (1 - (i1 - i0) / max(1, t1 - t0)) for (t0, i0), (t1, i1) in zip(before, now)]

    def memory(self):
        info = {}
        for line in _read("/proc/meminfo").split("\n"):
            key, _, value = line.partition(":")
            if value:
                info[key] = int(value.split()[0])
        return info["MemTotal"] // 1024, (info["MemTotal"] - info["MemAvailable"]) // 1024

    def temperature(self):
        return int(_read("/sys/class/thermal/thermal_zone0/temp")) / 1000

    def network(self):
        # kB/s received and sent by each interface but lo, since the last call.
        counts = {}
        for line in _read("/proc/net/dev").split("\n")[2:]:
            if ":" in line:
                name, _, rest = line.partition(":")
                fields = rest.split()
                if name.strip() != "lo":
                    counts[name.strip()] = (int(fields[0]), int(fields[8]))
        now = time.ticks_ms()
        before, at = self._net, self._net_at
        self._net, self._net_at = counts, now
        if not before:
            return {name: (0.0, 0.0) for name in counts}
        seconds = max(0.001, time.ticks_diff(now, at) / 1000)
        return {name: ((rx - before.get(name, (rx, tx))[0]) / 1024 / seconds,
                       (tx - before.get(name, (rx, tx))[1]) / 1024 / seconds)
                for name, (rx, tx) in counts.items()}

    def uptime(self):
        return float(_read("/proc/uptime").split()[0])

    def load(self):
        return _read("/proc/loadavg").split()[0]

    def m4(self):
        # (state, firmware, channel, [round trips in us])
        state = _read("/sys/class/remoteproc/remoteproc0/state").strip()
        firmware = mpy_m4.info()
        trips = []
        for _ in range(20):
            start = time.ticks_us()
            mpy_m4.link.request(1)
            trips.append(time.ticks_diff(time.ticks_us(), start))
        return state, firmware, mpy_m4.link.transport, trips


class Simulated:
    def __init__(self):
        self._n = 0

    def cpu(self):
        self._n += 1
        return [20 + 15 * ((self._n * 7) % 10) / 10, 5 + 10 * ((self._n * 3) % 10) / 10]

    def memory(self):
        return 432, 180 + self._n % 20

    def temperature(self):
        return 38.5

    def network(self):
        return {"wlan0": (12.0 + self._n % 30, 3.0), "usb0": (0.4, 0.8)}

    def uptime(self):
        return 3600 + self._n

    def load(self):
        return "0.35"

    def m4(self):
        return "running", "mpy-m4 stm32mp157c-dk2", "simulator", [290 + (i * 7) % 40 for i in range(20)]


probes = Board() if HARDWARE else Simulated()
